import{_ as o,C as s,o as r,c as n,ai as e,G as i}from"./chunks/framework.CUYGB37K.js";const f=JSON.parse('{"title":"Magic AI — Prompts","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/magic-ai/prompts.md","filePath":"2.0/magic-ai/prompts.md","lastUpdated":1779083873000}'),p={name:"2.0/magic-ai/prompts.md"};function d(l,t,c,h,m,g){const a=s("ImagePopup");return r(),n("div",null,[t[0]||(t[0]=e('<h1 id="magic-ai-—-prompts" tabindex="-1">Magic AI — Prompts <a class="header-anchor" href="#magic-ai-—-prompts" aria-label="Permalink to &quot;Magic AI — Prompts&quot;">​</a></h1><blockquote><p><strong>Sidebar:</strong> Magic AI → <strong>Prompts</strong><strong>URL:</strong> <code>/admin/magic-ai/prompts</code></p></blockquote><p>The <strong>Prompts</strong> page is where you manage the <strong>instruction templates</strong> that Magic AI sends to the model with every request. A well-written prompt is what makes the difference between generic AI filler and content that fits your brand and catalog.</p><h2 id="what-is-a-prompt" tabindex="-1">What is a Prompt? <a class="header-anchor" href="#what-is-a-prompt" aria-label="Permalink to &quot;What is a Prompt?&quot;">​</a></h2><p>A <em>Prompt</em> is an instruction that tells the AI <em>what</em> to produce for a specific field. It&#39;s a short piece of text with optional <strong>placeholders</strong> — tokens like <code>@name</code>, <code>@color</code>, <code>@material</code> — that Magic AI replaces with real values from the entity at generation time.</p><p>Example prompt:</p><blockquote><p><code>Write a detailed product description for @name highlighting its features, benefits, and @color variant.</code></p></blockquote><p>When this prompt runs against a product named <em>Air Max 90</em> with <code>color = Blue</code>, it becomes:</p><blockquote><p><code>Write a detailed product description for Air Max 90 highlighting its features, benefits, and Blue variant.</code></p></blockquote><p>Every prompt is tied to two axes:</p><ul><li><strong>Entity Type</strong> — which kind of record it applies to: <code>product</code> or <code>category</code>.</li><li><strong>Purpose</strong> — what it produces: <code>Text Generation</code> or <code>Image Generation</code>.</li></ul><p>Magic AI picks the matching prompt automatically when you click a wand icon, run auto-enrichment, or ask the AI Agent to generate content.</p><h2 id="what-does-this-page-do" tabindex="-1">What does this page do? <a class="header-anchor" href="#what-does-this-page-do" aria-label="Permalink to &quot;What does this page do?&quot;">​</a></h2><ul><li>Lists every prompt template available in the system.</li><li>Lets you <strong>create</strong>, <strong>edit</strong>, and <strong>delete</strong> prompts.</li><li>Shows which entity and purpose each prompt serves, so you can see coverage at a glance.</li></ul>',14)),i(a,{src:"/assets/2.0/images/magic-ai/prompts.png",alt:"Prompts"}),t[1]||(t[1]=e(`<h2 id="how-prompts-are-used-at-generation-time" tabindex="-1">How prompts are used at generation time <a class="header-anchor" href="#how-prompts-are-used-at-generation-time" aria-label="Permalink to &quot;How prompts are used at generation time&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User clicks wand icon on a field</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>Magic AI picks the prompt that matches</span></span>
<span class="line"><span>   entity type (product/category) + purpose (text/image)</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>\`@attribute_code\` placeholders are replaced</span></span>
<span class="line"><span>   with the entity&#39;s real attribute values</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>Active System Prompt (tone + temperature) is prepended</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>Request sent to the Platform + Model</span></span>
<span class="line"><span>   configured on Magic AI → Settings</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>Generated content appears in the field</span></span></code></pre></div><h2 id="prompts-datagrid" tabindex="-1">Prompts datagrid <a class="header-anchor" href="#prompts-datagrid" aria-label="Permalink to &quot;Prompts datagrid&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Title</strong></td><td>The name of the prompt.</td></tr><tr><td><strong>Prompt</strong></td><td>The prompt text with placeholders.</td></tr><tr><td><strong>Entity Type</strong></td><td>The entity the prompt applies to (<code>product</code> or <code>category</code>).</td></tr><tr><td><strong>Purpose</strong></td><td>Whether the prompt is for <code>Text Generation</code> or <code>Image Generation</code>.</td></tr><tr><td><strong>Created At</strong></td><td>Date the prompt was created.</td></tr><tr><td><strong>Updated At</strong></td><td>Date the prompt was last modified.</td></tr><tr><td><strong>Actions</strong></td><td>Edit (pencil icon), Delete (trash icon).</td></tr></tbody></table><h2 id="creating-a-prompt" tabindex="-1">Creating a Prompt <a class="header-anchor" href="#creating-a-prompt" aria-label="Permalink to &quot;Creating a Prompt&quot;">​</a></h2><p>Click the <strong>Create Prompt</strong> button. Fill in:</p><ul><li><strong>Title</strong> — How it appears in the list. Use something recognisable like <em>&quot;Product Description — Long Form&quot;</em>.</li><li><strong>Prompt</strong> — The instruction text. Use <code>@attribute_code</code> placeholders for any value you want pulled from the entity. You can reference any attribute code defined on the entity&#39;s attribute family.</li><li><strong>Entity Type</strong> — <code>product</code> or <code>category</code>.</li><li><strong>Purpose</strong> — <code>Text Generation</code> or <code>Image Generation</code>.</li></ul><h3 id="placeholder-rules" tabindex="-1">Placeholder rules <a class="header-anchor" href="#placeholder-rules" aria-label="Permalink to &quot;Placeholder rules&quot;">​</a></h3><ul><li>Placeholders are prefixed with <code>@</code> and use the <strong>attribute code</strong>, not the label. For example, a &quot;Product Color&quot; attribute with code <code>color</code> is referenced as <code>@color</code>.</li><li>If the attribute has no value on the entity, the placeholder is replaced with an empty string — so write prompts defensively (e.g., <code>highlighting its @color variant if specified</code>).</li><li>You can chain multiple placeholders in one prompt; Magic AI expands them all in a single pass.</li></ul><h2 id="example-prompts" tabindex="-1">Example Prompts <a class="header-anchor" href="#example-prompts" aria-label="Permalink to &quot;Example Prompts&quot;">​</a></h2><p>Here are examples of prompts that ship with UnoPim:</p><table tabindex="0"><thead><tr><th>Title</th><th>Prompt</th><th>Entity Type</th><th>Purpose</th></tr></thead><tbody><tr><td>AI Product Description</td><td>Write a detailed product description for @name highlighting its features, benefits and @color variant.</td><td>product</td><td>Text Generation</td></tr><tr><td>AI Product Image</td><td>Generate a professional product photo of @name on a clean white background with studio lighting.</td><td>product</td><td>Image Generation</td></tr><tr><td>AI Category Description</td><td>Write a compelling category description for @name that helps customers browse products.</td><td>category</td><td>Text Generation</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use attribute codes as placeholders (prefixed with <code>@</code>) in your prompts. Magic AI replaces them with actual values from the product or category being processed.</p></div><h2 id="prompts-vs-system-prompts-—-what-s-the-difference" tabindex="-1">Prompts vs. System Prompts — what&#39;s the difference? <a class="header-anchor" href="#prompts-vs-system-prompts-—-what-s-the-difference" aria-label="Permalink to &quot;Prompts vs. System Prompts — what&#39;s the difference?&quot;">​</a></h2><ul><li>A <strong>Prompt</strong> says <em>what</em> to write for a specific field (&quot;write a product description that mentions <code>@name</code> and <code>@color</code>&quot;).</li><li>A <strong>System Prompt</strong> says <em>how</em> to write — voice, tone, creativity, length. It applies globally, in front of every prompt.</li></ul><p>See the <strong><a href="./system-prompts.html">System Prompts</a></strong> page for the personality layer that sits underneath every prompt.</p>`,16))])}const b=o(p,[["render",d]]);export{f as __pageData,b as default};
